/* User module-control overrides (bit set in mask = value is forced). */
static uint32_t t41_modctl_mask, t41_modctl_value;

static int t41_top_restore_bypass(uint32_t mask)
{
	uint32_t *bypass = &((uint32_t *)(void *)top_bypass_global)[0];
	const uint8_t *params = (const uint8_t *)(uintptr_t)
		((uint32_t *)(void *)tparamsP_storage)[0];
	if (!params || tx_isp_top_restore(params + 4, 32, mask, bypass))
		return -EINVAL;
	/* IMP_ISP_Tuning_SetModuleControl overrides outlive the calibration
	 * restore of the module's own refresh path. */
	*bypass = (*bypass & ~t41_modctl_mask) | (t41_modctl_value & t41_modctl_mask);
	system_reg_write(0x40, *bypass);
	return 0;
}

static int t41_apply_flicker_profile(bool enable)
{
	uint32_t *bypass = &((uint32_t *)(void *)top_bypass_global)[0];
	const uint8_t *params = (const uint8_t *)(uintptr_t)
		((uint32_t *)(void *)tparamsP_storage)[0];
	int ret;

	/* tisp_top_write_bypass owns one calibration byte per TOP bit.
	 * Restore bit 9, not a stock scene's entire captured TOP word. */
	if (!params || params[4 + 9] > 1)
		return -EINVAL;
	ret = tx_isp_t41_flicker_profile_apply(
		0, enable, t41_ae_flicker_gib_gain_q10,
		t41_color_green_correction_q10,
		t41_color_blue_correction_q10, params[4 + 9], bypass);
	t41_trace_printk(KERN_WARNING
	       "t41: flicker image profile %s "
	       "gib=%#x correction=%#x/%#x bypass=%#x ret=%d\n",
	       enable ? "enabled" : "disabled",
	       t41_ae_flicker_gib_gain_q10,
	       t41_color_green_correction_q10,
	       t41_color_blue_correction_q10, *bypass, ret);
	return ret;
}

static int t41_flicker_profile_set(const char *value,
				   const struct kernel_param *kp)
{
	int ret = param_set_int(value, kp);
	uint32_t bypass;

	if (ret)
		return ret;

	/*
	 * Parameter parsing also runs before TISP owns the register bank.  Its
	 * initialized TOP word always carries the upper reserved bits, so only
	 * perform a live transition after that ownership point.
	 */
	bypass = ((uint32_t *)(void *)top_bypass_global)[0];
	if (bypass & 0xfc000000U)
		ret = t41_apply_flicker_profile(
			t41_ae_antiflicker_request == ~0U &&
			t41_ae_flicker_profile < 0 &&
			t41_ae_flicker_frequency_hz &&
			t41_ae_flicker_floor_lines);
	return ret;
}

