static inline int32_t sx_d(uint8_t v) {
    return (int32_t)(int8_t)v;
}
static inline uint8_t interp_signed(int32_t a, int32_t b, uint32_t w) {
    int64_t val = (int64_t)sx_d(a) * (int64_t)(256 - w) + (int64_t)sx_d(b) * (int64_t)w;
    return (uint8_t)((val + 128) >> 8);
}
static inline uint8_t interp_unsigned(uint32_t a, uint32_t b, uint32_t w) {
    int64_t val = (int64_t)zx_d(a) * (int64_t)(256 - w) + (int64_t)zx_d(b) * (int64_t)w;
    return (uint8_t)((val + 128) >> 8);
}
