                request.id == TX_ISP_TUNING_CMD_T41_AWB_CT_TREND ? T41_AWB_TREND :
                request.id == TX_ISP_TUNING_CMD_T41_AWB_CONVERGE ? T41_AWB_CONVERGE : T41_AWB_ZONE;
