static void t41_apply_stock_awb_gains(void)
{
    uint32_t gains[2] = { t41_stock_awb_gain_a, t41_stock_awb_gain_b };
    uint32_t words[2], gain_a, gain_b;

    if (t41_native_awb) { t41_native_awb_writer(0, 0); return; }

    if (!gains[0] && !gains[1]) {
        int ret = (int)tisp_awb_set_gain(0);
        if (ret < 0)
            printk(KERN_WARNING "t41: calibrated WB seed unavailable: %d\n", ret);
        return;
    }
    if (!gains[0] || !gains[1])
        return;
    t41_awb_gain_pack(gains, words);
    gain_a = words[0]; gain_b = words[1];

    /* T23 and T40 use the same two-bank ownership sequence: populate bank two,
     * commit it, then populate and commit bank three.  Committing only bank
     * three works during cold init but leaves bank two stale when gains are
     * calibrated at runtime. */
    system_reg_write(0x04004, gain_a);
    system_reg_write(0x04008, gain_b);
    system_reg_write(0x0400c, gain_a);
    system_reg_write(0x04010, gain_b);
    system_reg_set_awb_trig(2, 0);
    system_reg_write(0x05004, gain_a);
    system_reg_write(0x05008, gain_b);
    system_reg_write(0x0500c, gain_a);
    system_reg_write(0x05010, gain_b);
    system_reg_set_awb_trig(3, 0);
    t41_awb_last_rgain = t41_stock_awb_gain_a;
    t41_awb_last_bgain = t41_stock_awb_gain_b;
    pr_debug("calibrated AWB gains a=%#x b=%#x read=%#x/%#x/%#x/%#x\n",
           t41_stock_awb_gain_a, t41_stock_awb_gain_b,
           system_reg_read(0x04004), system_reg_read(0x04008),
           system_reg_read(0x05004), system_reg_read(0x05008));
}

static void t41_apply_stock_awb_stats_profile(void)
{
    uint8_t *info, *params;
    uint32_t words[10];

    if (t41_native_awb) {
        t41_native_awb_writer(0, 1);
        return;
    }

    /* Compatibility selector, no captured register image. Reapply only
     * writer-owned setup/thresholds; do not reset the running DMA ring. */
    if (t41_stock_awb_stats_profile > 0 || !awb_info[0])
        return;
    info = (uint8_t *)(uintptr_t)awb_info[0];
    if (!t41_kernel_data_ptr(info))
        return;
    params = (uint8_t *)(uintptr_t)*(uint32_t *)(void *)info;
    if (!t41_kernel_data_ptr(params) ||
        t41_awb_geometry(params, T41_AWB_HW_PARAM_BYTES, words))
        return;
    system_reg_write(0x18004, words[0]);
    tisp_awb_set_regional_threshold(0);
    tisp_awb_set_lum_th_freq(0);
    system_reg_set_awb_trig(1, 0);
    printk(KERN_INFO
           "t41: calibration-driven AWB setup=%#x thresholds=%#x/%#x/%#x/%#x/%#x\n",
           words[0], system_reg_read(0x18028), system_reg_read(0x1802c),
           system_reg_read(0x18030), system_reg_read(0x18034),
           system_reg_read(0x18038));
}

static void t41_safe_awb_apply(uint32_t rgain, uint32_t bgain)
{
    uint32_t rvalue = 0x04000000U | (rgain & 0x3fffU);
    uint32_t bvalue = 0x04000000U | (bgain & 0x3fffU);

    system_reg_write(0x04004U, rvalue);
    system_reg_write(0x04008U, bvalue);
    system_reg_write(0x0400cU, rvalue);
    system_reg_write(0x04010U, bvalue);
    system_reg_set_awb_trig(2, 0);
    system_reg_write(0x05004U, rvalue);
    system_reg_write(0x05008U, bvalue);
    system_reg_write(0x0500cU, rvalue);
    system_reg_write(0x05010U, bvalue);
    system_reg_set_awb_trig(3, 0);
}

/* Return the legacy whole-scene color signal without enabling the experimental
 * AWB writer. Aggregate the four temporal DMA banks to smooth their updates;
 * calibrated neutral selection is exposed separately by AWB_TARGET. */
static int t41_safe_awb_measure_scene(struct tx_isp_tuning_awb_scene *scene)
{
    if (t41_native_awb) return t41_native_awb_observe(0, (unsigned int *)scene);
    uint8_t *info;
    uint8_t *params;
    uint8_t *dma;
    uint32_t bank_size;
    uint32_t bank;
    uint32_t grid_rows;
    uint32_t grid_columns;
    uint32_t grid_groups;
    uint64_t red = 0;
    uint64_t green = 0;
    uint64_t blue = 0;
    uint64_t pixels = 0;
    uint32_t zones = 0;

    if (!scene || !awb_info[0])
        return -EINVAL;
    info = (uint8_t *)(uintptr_t)awb_info[0];
    if (!t41_kernel_data_ptr(info))
        return -ENODEV;
    params = (uint8_t *)(uintptr_t)*(uint32_t *)(void *)(info + 0);
    dma = (uint8_t *)(uintptr_t)*(uint32_t *)(void *)(info + 20);
    if (!t41_kernel_data_ptr(params) || !t41_kernel_data_ptr(dma))
        return -ENODEV;

    bank_size = ((8U - 6U * params[3274]) & 0xffU) << 12;
    if (!bank_size || bank_size > 0x8000U)
        return -EINVAL;
    grid_rows = *(uint16_t *)(void *)(params + 3182);
    grid_columns = *(uint16_t *)(void *)(params + 3186);
    if (!grid_rows || !grid_columns || grid_rows > 15U ||
        grid_columns > 15U || params[3274] != 0U)
        return -EINVAL;
    grid_groups = grid_rows * grid_columns;
    if (grid_groups > bank_size / 128U)
        return -EINVAL;
    for (bank = 0; bank < 4U; ++bank) {
        uint8_t *source = dma + bank * bank_size;
        uint32_t group;

        if (!t41_kernel_data_ptr(source) ||
            !t41_kernel_data_ptr(source + bank_size - 1U))
            return -ENODEV;
        dma_cache_sync(NULL, source, bank_size, DMA_FROM_DEVICE);
        /* The bank allocation is 32 KiB, but the configured 15x15 grid
         * occupies only 225 packed 128-byte groups. The unused allocation
         * tail is not cleared consistently across boots; treating it as
         * active zones made the aggregate ratios jump with stale data. */
        for (group = 0; group < grid_groups; ++group) {
            uint32_t off = group * 128U;
            uint32_t rec;

            for (rec = 0; rec < 128U; rec += 16U) {
                uint8_t *record = source + off + rec;
                uint32_t w0 = *(uint32_t *)(void *)(record + 0);
                uint32_t w1 = *(uint32_t *)(void *)(record + 4);
                uint32_t w2 = *(uint32_t *)(void *)(record + 8);
                uint32_t w3 = *(uint32_t *)(void *)(record + 12);
                uint32_t count = ((w3 & 0x3fU) << 8) | (w2 >> 24);

                if (!count)
                    continue;
                red += w0 & 0x3fffffU;
                green += ((w1 & 0xfffU) << 10) | (w0 >> 22);
                blue += ((w2 & 3U) << 20) | (w1 >> 12);
                pixels += count;
                zones++;
            }
        }
    }

    /* Keep the statistics engine live while manual gains remain installed. */
    system_reg_set_awb_trig(1, 0);
    if (zones < t41_awb_min_zones * 4U ||
        pixels < (uint64_t)t41_awb_min_pixels * 4U ||
        !red || !green || !blue)
        return -ENODATA;
    scene->raw_r_q10 = (uint32_t)div64_u64(green << 10, red);
    scene->raw_b_q10 = (uint32_t)div64_u64(green << 10, blue);
    return 0;
}

/* Bounded neutral-mesh estimator, not the unsafe recovered OEM AWB process.
 * H20250310a tisp_awb_long_par_update (0x30b70), long_alogrithm (0x31288)
 * and ct_detect (0x1b260) identify the calibration, ratio axes, selection
 * mesh and spatial weights below. File AWB +3352 maps to runtime +2424.
 * This uses those sensor-owned data but intentionally omits OEM clustering,
 * clustering/history and CT-dependent additive gain corrections.
 * CT priors and neutral-selection weights are calibration-driven. */
static int t41_safe_awb_measure_target(struct tx_isp_tuning_awb_target *target)
{
    if (t41_native_awb) return t41_native_awb_observe(1, (unsigned int *)target);
    struct tx_isp_awb_mesh mesh = { 0 };
    struct tx_isp_awb_ct_config ct_config;
    struct tx_isp_awb_accumulator sum = { 0 };
    uint8_t *info, *params, *dma;
    uint32_t rows, columns, bank, group, bin, weight_sum = 0;
    uint32_t integration, gain_q16, gain_q10, ev;
    uint32_t bin_weights[4];
    uint64_t pixels = 0;
    int ret;

    if (!target || !awb_info[0])
        return -ENODEV;
    info = (uint8_t *)(uintptr_t)awb_info[0];
    if (!t41_kernel_data_ptr(info))
        return -ENODEV;
    params = (uint8_t *)(uintptr_t)*(uint32_t *)(void *)info;
    dma = (uint8_t *)(uintptr_t)*(uint32_t *)(void *)(info + 20);
    if (!t41_kernel_data_ptr(params) || !t41_kernel_data_ptr(dma) ||
        !t41_kernel_data_ptr(dma + 131071))
        return -ENODEV;
    rows = *(uint16_t *)(void *)(params + 3182);
    columns = *(uint16_t *)(void *)(params + 3186);
    if (!rows || !columns || rows > 15 || columns > 15 || params[3274])
        return -EINVAL;
    mesh.red_axis = (uint32_t *)(void *)(params + 0x38);
    mesh.blue_axis = (uint32_t *)(void *)(params + 0x74);
    mesh.weights = (uint32_t *)(void *)(params + 0x4ec);
    mesh.red_calibration_q10 = *(uint32_t *)(void *)(params + 0x30);
    mesh.blue_calibration_q10 = *(uint32_t *)(void *)(params + 0x34);
    /* Do not infer gain bias from the adjacent, unreferenced +0xcde/+0xce0
     * tuning words. The OEM gain writer's CT-dependent additive offsets
     * (+0xbf4..+0xc08) require a recovered CT estimate, which this bounded
     * estimator does not yet provide. Keep the raw neutral ratio unbiased. */
    mesh.red_bias_q10 = 1024U;
    mesh.blue_bias_q10 = 1024U;
    /* The neutral estimator uses the sensor's reciprocal-temperature
     * mesh and EV-dependent CT prior. These are selection weights, not
     * post-gain biases. See long_par_update 0x30b70 and ct_detect 0x1b260. */
    integration = READ_ONCE(t41_safe_ae_integration);
    gain_q16 = READ_ONCE(t41_safe_ae_gain_q16);
    if (integration == ~0U || gain_q16 == ~0U || gain_q16 > (10U << 16))
        return -EAGAIN;
    gain_q10 = tx_isp_exp2_u32(gain_q16, 16, 10);
    ev = (uint32_t)min_t(uint64_t, 0x3fffffffU,
        ((uint64_t)integration * gain_q10) >> 10);
    ct_config.ev_low = *(uint32_t *)(void *)(params + 0x1c);
    ct_config.ev_high = *(uint32_t *)(void *)(params + 0x20);
    memcpy(ct_config.day, params + 0xb0, sizeof(ct_config.day));
    memcpy(ct_config.transition, params + 0xc0, sizeof(ct_config.transition));
    memcpy(ct_config.night, params + 0xd0, sizeof(ct_config.night));
    ct_config.day_enabled = *(uint32_t *)(void *)(params + 0xe0);
    ct_config.day_floor_q8 = *(uint32_t *)(void *)(params + 0xe4);
    ct_config.night_enabled = *(uint32_t *)(void *)(params + 0xe8);
    ct_config.night_floor_q8 = *(uint32_t *)(void *)(params + 0xec);
    ret = tx_isp_awb_ct_prior_build(&ct_config, ev, &mesh.ct_prior);
    if (ret)
        return ret;
    mesh.ct_mired = (uint32_t *)(void *)(params + 0x870);
    ret = tx_isp_awb_mesh_validate(&mesh);
    if (ret)
        return ret;
    for (bin = 0; bin < 4; ++bin) {
        bin_weights[bin] = *(uint16_t *)(void *)(params + 0xd46 + bin * 2);
        if (bin_weights[bin] > 16)
            return -EINVAL;
        weight_sum += bin_weights[bin];
    }
    if (!weight_sum)
        return -ENODATA;

    /* Four temporal banks, four luminance classes. Odd records feed the
     * OEM neutral estimator (runtime +0x1c20); even records feed its
     * separate global estimator (+0x2328). Do not mix their selections.
     * get_statistics 0x30590 -> long_alogrithm 0x31288 -> long_par_update
     * 0x30d2c establishes this mapping, rather than a spatial-phase model. */
    for (bank = 0; bank < 4; ++bank) {
        uint8_t *source = dma + bank * 32768U;

        dma_cache_sync(NULL, source, 32768U, DMA_FROM_DEVICE);
        for (group = 0; group < rows * columns; ++group) {
            uint32_t r = 0, g = 0, b = 0, count = 0;
            uint32_t spatial = params[0x1200 + group];

            if (!spatial)
                continue;
            for (bin = 0; bin < 4; ++bin) {
                uint32_t weight = bin_weights[bin];
                if (!weight)
                    continue;
                {
                    uint32_t *v = (uint32_t *)(void *)(source +
                        group * 128U + (bin * 2 + 1) * 16U);
                    uint32_t w0 = READ_ONCE(v[0]), w1 = READ_ONCE(v[1]);
                    uint32_t w2 = READ_ONCE(v[2]), w3 = READ_ONCE(v[3]);
                    uint32_t n = ((w3 & 63U) << 8) | (w2 >> 24);

                    if (!n)
                        continue;
                    r += (w0 & 0x3fffffU) * weight;
                    g += (((w1 & 0xfffU) << 10) | (w0 >> 22)) * weight;
                    b += (((w2 & 3U) << 20) | (w1 >> 12)) * weight;
                    count += n * weight;
                }
            }
            /* OEM class weights are Q3, including the pixel-count plane. */
            count >>= 3;
            if (count <= *(uint32_t *)(void *)params)
                continue;
            if (tx_isp_awb_mesh_add(&mesh, &sum, r >> 3,
                                    g >> 3, b >> 3, spatial))
                pixels += count;
        }
    }
    system_reg_set_awb_trig(1, 0);
    if (pixels < (uint64_t)t41_awb_min_pixels * 4U)
        return -ENODATA;
    ret = tx_isp_awb_mesh_result(&mesh, &sum,
        max_t(uint32_t, 1U, t41_awb_min_zones) * 4U,
        &target->r_gain_q10, &target->b_gain_q10);
    if (!ret) {
        uint32_t ct;
        if (!tx_isp_awb_mesh_temperature(&mesh,
            target->r_gain_q10 * 1024U / mesh.red_bias_q10,
            target->b_gain_q10 * 1024U / mesh.blue_bias_q10, &ct))
            WRITE_ONCE(t41_ccm_ct, ct);
    }
    return ret;
}

static bool t41_safe_awb_ratio_close(uint32_t value, uint32_t reference)
{
    uint32_t tolerance = max_t(uint32_t, reference >> 3, 1U);

    return value >= reference - min(reference, tolerance) &&
           value <= reference + tolerance;
}

static int32_t t41_safe_awb_interrupt(uint32_t channel)
{
    uint8_t *info;
    uint8_t *params;
    uint8_t *dma;
    uint8_t *source;
    uint32_t bank_size;
    uint32_t bank;
    uint32_t off;
    uint32_t rec;
    uint32_t zones = 0;
    uint64_t red = 0;
    uint64_t green = 0;
    uint64_t blue = 0;
    uint64_t pixels = 0;
    uint32_t raw_r;
    uint32_t raw_b;
    uint32_t target_r;
    uint32_t target_b;

    if (channel >= 2 || !awb_info[channel])
        return -EINVAL;
    info = (uint8_t *)(uintptr_t)awb_info[channel];
    if (!t41_kernel_data_ptr(info))
        return -EINVAL;
    params = (uint8_t *)(uintptr_t)*(uint32_t *)(void *)(info + 0);
    dma = (uint8_t *)(uintptr_t)*(uint32_t *)(void *)(info + 20);
    if (!t41_kernel_data_ptr(params) || !t41_kernel_data_ptr(dma))
        return -EINVAL;

    bank_size = ((8U - 6U * params[3274]) & 0xffU) << 12;
    /* Exact T41 tisp_awb_main_interrupt_static consumes the bank named by
     * 0x18050 directly.  T40's preceding-bank rule does not apply here. */
    bank = (uint32_t)system_reg_read(0x18050U) & 3U;
    t41_awb_last_bank = bank;
    if (!bank_size || bank_size > 0x8000U)
        return -EINVAL;
    source = dma + bank * bank_size;
    if (!t41_kernel_data_ptr(source) ||
        !t41_kernel_data_ptr(source + bank_size - 1U))
        return -EINVAL;

    dma_cache_sync(NULL, source, bank_size, DMA_FROM_DEVICE);
    for (off = 0; off + 128U <= bank_size; off += 128U) {
        /* The OEM parser consumes all eight packed records in each group.
         * Sampling only record zero makes the result depend on the spatial
         * phase: it looked plausible in bank zero but changed by several
         * times when the hardware advanced to banks one and two. */
        for (rec = 0; rec < 128U; rec += 16U) {
            uint8_t *record = source + off + rec;
            uint32_t w0 = *(uint32_t *)(void *)(record + 0);
            uint32_t w1 = *(uint32_t *)(void *)(record + 4);
            uint32_t w2 = *(uint32_t *)(void *)(record + 8);
            uint32_t w3 = *(uint32_t *)(void *)(record + 12);
            uint32_t count = ((w3 & 0x3fU) << 8) | (w2 >> 24);

            if (!count)
                continue;
            red += w0 & 0x3fffffU;
            green += ((w1 & 0xfffU) << 10) | (w0 >> 22);
            blue += ((w2 & 3U) << 20) | (w1 >> 12);
            pixels += count;
            zones++;
        }
    }

    t41_awb_irq_count = (t41_awb_irq_count & 0x7fffffffU) + 1U;
    if (!zones || !red || !green || !blue ||
        zones < t41_awb_min_zones || pixels < t41_awb_min_pixels)
        goto trace;
    if (t41_awb_irq_count <= t41_awb_warmup_irqs)
        goto trace;
    if (t41_awb_update_irqs > 1U &&
        t41_awb_irq_count % t41_awb_update_irqs)
        goto trace;

    /*
     * The packed AWB statistic is taken before WB multiplication.  Its
     * G/R and G/B ratios therefore map directly to target gains through the
     * OS04D10 calibration constants; multiplying by the current gain turns
     * the loop into positive feedback and drives both channels to 0x1800.
     */
    raw_r = (uint32_t)div64_u64(green << 10, red);
    raw_b = (uint32_t)div64_u64(green << 10, blue);

    /* The T41 statistic engine occasionally exposes a partially replaced
     * zone group while its DMA ring advances.  Those bursts last less than
     * two seconds in controlled captures and shift both ratios by 20-60%,
     * enough to create a visible green flash despite output damping.  Accept
     * ratios near the settled estimate immediately.  A real illuminant step
     * is still accepted after 32 mutually consistent samples (about five
     * seconds at the default every-other-interrupt update rate). */
    if (!t41_safe_awb_ratio_close(raw_r, t41_awb_last_raw_r_q10) ||
        !t41_safe_awb_ratio_close(raw_b, t41_awb_last_raw_b_q10)) {
        if (t41_safe_awb_ratio_close(raw_r, t41_awb_outlier_r_q10) &&
            t41_safe_awb_ratio_close(raw_b, t41_awb_outlier_b_q10)) {
            t41_awb_outlier_count =
                (t41_awb_outlier_count & 0x7fffffffU) + 1U;
        } else {
            t41_awb_outlier_r_q10 = raw_r;
            t41_awb_outlier_b_q10 = raw_b;
            t41_awb_outlier_count = 1U;
        }
        if (t41_awb_outlier_count < 32U) {
            t41_awb_reject_count =
                (t41_awb_reject_count & 0x7fffffffU) + 1U;
            goto trace;
        }
    }
    t41_awb_last_raw_r_q10 = raw_r;
    t41_awb_last_raw_b_q10 = raw_b;
    t41_awb_outlier_r_q10 = raw_r;
    t41_awb_outlier_b_q10 = raw_b;
    t41_awb_outlier_count = 0U;
    target_r = raw_r;
    target_b = raw_b;
    target_r = clamp_t(uint32_t, target_r, 0x200U, 0x1800U);
    target_b = clamp_t(uint32_t, target_b, 0x200U, 0x1800U);

    /* Match the proven T40/T23 controller damping: one-eighth of the new
     * estimate per update avoids visible color hunting. */
    t41_awb_last_rgain =
        (t41_awb_last_rgain * 7U + target_r) / 8U;
    t41_awb_last_bgain =
        (t41_awb_last_bgain * 7U + target_b) / 8U;
    t41_safe_awb_apply(t41_awb_last_rgain, t41_awb_last_bgain);
    t41_awb_update_count =
        (t41_awb_update_count & 0x7fffffffU) + 1U;

trace:
    if (t41_awb_irq_count <= 12U ||
        !(t41_awb_irq_count & (t41_awb_irq_count - 1U)))
        printk(KERN_WARNING
               "t41: safe AWB irq=%u update=%u reject=%u bank=%u zones=%u pixels=%llu rgb=%llu/%llu/%llu gains=%#x/%#x\n",
               t41_awb_irq_count, t41_awb_update_count,
               t41_awb_reject_count, bank, zones,
               (unsigned long long)pixels, (unsigned long long)red,
               (unsigned long long)green, (unsigned long long)blue,
               t41_awb_last_rgain, t41_awb_last_bgain);
rearm:
    /* AWB statistics are one-shot on T40/T23 and T41.  The full vendor AWB
     * process normally rearms them as part of its register transaction. */
    system_reg_set_awb_trig(1, 0);
    return zones ? 1 : -ENODATA;
}

static void t41_safe_awb_workfn(struct work_struct *work)
{
    t41_heapwatch_mark("t41_safe_awb_workfn");
    (void)work;
    t41_safe_awb_interrupt(0);
}

static int t41_safe_awb_controller_set(const char *value,
				       const struct kernel_param *kp)
{
    int was_enabled = t41_safe_awb_controller < 0;
    int ret = param_set_int(value, kp);

    if (ret)
        return ret;
    if (t41_safe_awb_controller < 0) {
        /* AWB statistics are one-shot.  A controller enabled after stream-on
         * otherwise waits forever because the ignored startup completion was
         * never rearmed.  Reapply only the writer-owned setup words and start
         * a fresh warmup window before accepting DMA statistics. */
        t41_awb_irq_count = 0x80000000U;
        t41_awb_update_count = 0x80000000U;
        t41_awb_reject_count = 0x80000000U;
        t41_awb_last_bank = 0x80000000U;
        t41_awb_last_raw_r_q10 = t41_awb_last_rgain;
        t41_awb_last_raw_b_q10 = t41_awb_last_bgain;
        t41_awb_outlier_r_q10 = t41_awb_last_raw_r_q10;
        t41_awb_outlier_b_q10 = t41_awb_last_raw_b_q10;
        t41_awb_outlier_count = 0x80000000U;
        t41_apply_stock_awb_stats_profile();
    } else if (was_enabled) {
        cancel_work_sync(&t41_safe_awb_work);
        t41_apply_stock_awb_gains();
    }
    return 0;
}

static int t41_safe_awb_configure(uint32_t mode, uint16_t rgain,
                                  uint16_t bgain)
{
    int was_enabled = READ_ONCE(t41_safe_awb_controller) < 0;

    if (t41_native_awb)
        return t41_native_awb_compat(mode, rgain, bgain, 0, NULL);

    if (mode > TX_ISP_TUNING_AWB_AUTO || rgain < 0x200U ||
        rgain > 0x1800U || bgain < 0x200U || bgain > 0x1800U)
        return -EINVAL;

    /* Stop future IRQ fan-out before waiting for an in-flight worker.  The
     * subsequent two-bank write is then an indivisible profile handoff from
     * userspace's point of view; capture and encoding remain untouched. */
    if (mode == TX_ISP_TUNING_AWB_MANUAL) {
        WRITE_ONCE(t41_safe_awb_controller, 1);
        if (was_enabled)
            cancel_work_sync(&t41_safe_awb_work);
        t41_stock_awb_gain_a = rgain;
        t41_stock_awb_gain_b = bgain;
        t41_apply_stock_awb_gains();
    } else {
        if (was_enabled) {
            WRITE_ONCE(t41_safe_awb_controller, 1);
            cancel_work_sync(&t41_safe_awb_work);
        }
        t41_stock_awb_gain_a = rgain;
        t41_stock_awb_gain_b = bgain;
        t41_safe_awb_apply(rgain, bgain);
        t41_awb_last_rgain = rgain;
        t41_awb_last_bgain = bgain;
        WRITE_ONCE(t41_safe_awb_controller, -1);
        t41_awb_irq_count = 0x80000000U;
        t41_awb_update_count = 0x80000000U;
        t41_awb_reject_count = 0x80000000U;
        t41_awb_last_bank = 0x80000000U;
        t41_awb_last_raw_r_q10 = t41_awb_last_rgain;
        t41_awb_last_raw_b_q10 = t41_awb_last_bgain;
        t41_awb_outlier_r_q10 = t41_awb_last_raw_r_q10;
        t41_awb_outlier_b_q10 = t41_awb_last_raw_b_q10;
        t41_awb_outlier_count = 0x80000000U;
        t41_apply_stock_awb_stats_profile();
    }

    pr_debug("live AWB profile mode=%s gains=%#x/%#x\n",
           mode == TX_ISP_TUNING_AWB_AUTO ? "auto" : "manual",
           rgain, bgain);
    return 0;
}

static void t41_apply_stock_dpc_profile(void)
{
    /* Compatibility selector now refreshes calibrated writer-owned fields.
     * 0x7098 was in the captured delta but is not owned by the OEM writers. */
    if (t41_stock_dpc_profile > 0)
        return;
    t41_dpc_error = tisp_dpc_write_reg_part_0(0);
}

static int t41_apply_calibrated_bcsh(uint32_t color_model)
{
    uint32_t gain = READ_ONCE(t41_safe_ae_gain_q16);
    uint32_t integration = READ_ONCE(t41_safe_ae_integration);
    uint64_t ev = 0;
    int ret;

    if (gain <= (16U << 16) && integration != UINT_MAX)
        ev = (uint64_t)integration * tisp_math_exp2(gain, 16, 10) >> 10;
    ret = t41_bcsh_update(READ_ONCE(t41_ccm_ct),
                         min_t(uint64_t, ev, UINT_MAX), 1);
    if (!ret)
        WRITE_ONCE(t41_bcsh_color_model, color_model);
    return ret;
}

static void t41_apply_stock_dmsc_profile(void)
{
    uint32_t gain = READ_ONCE(t41_safe_ae_gain_q16);
    if (t41_stock_dmsc_profile > 0)
        return;
    if (gain > (16U << 16))
        gain = 0;
    t41_dmsc_error = tisp_dmsc_all_reg_refresh(0, gain);
}

static void t41_apply_stock_ysp_profile(void)
{
    uint32_t gain = READ_ONCE(t41_safe_ae_gain_q16);
    if (t41_stock_ysp_profile > 0)
        return;
    t41_ysp_error = tisp_ysp_all_reg_refresh(0, gain <= (16U << 16) ? gain : 0);
    if (!t41_ysp_error)
        t41_top_restore_bypass(BIT(17));
}

/* Lock order: frame-work mutex, LCE mutex, short statistics spinlock.
 * Only the IRQ owns histogram RAM reads; the worker owns all curve math. */
static uint8_t *t41_lce_object(void)
{
    uint8_t *s = (uint8_t *)(uintptr_t)lce_info;
    if (!t41_kernel_data_ptr(s) ||
        !t41_kernel_data_ptr((void *)(uintptr_t)t41_tmo_le32(s)))
        return NULL;
    return s;
}

static int t41_lce_calibrate_locked(uint8_t *s)
{
    return t41_lce_calibrate((uint8_t *)(uintptr_t)t41_tmo_le32(s),
        T41_LCE_PARAM_BYTES, s, T41_LCE_STATE_BYTES, t41_tmo_le32(s + 0x5900)) ? -EINVAL : 0;
}

static int t41_lce_write_locked(uint8_t *s)
{
    struct t41_dpc_word words[132];
    int count = t41_lce_pack_curve(s, T41_LCE_STATE_BYTES, words, ARRAY_SIZE(words)), i;
    if (count < 0)
        return -EINVAL;
    for (i = 0; i < count; ++i)
        system_reg_write(words[i].address, words[i].value);
    return 0;
}

static int t41_lce_frame(uint32_t gain)
{
    unsigned long flags;
    uint8_t *s;
    uint32_t old, ev;
    int ret = -ENODEV;
    mutex_lock(&t41_lce_lock);
    s = t41_lce_object();
    if (!s || t41_stock_lce_ram_profile > 0)
        goto done;
    old = t41_tmo_le32(s + 0x5900);
    if ((gain > old ? gain - old : old - gain) >= 128) {
        t41_lce_put32(s + 0x5900, gain);
        ret = t41_lce_calibrate_locked(s);
        if (ret)
            goto done;
    }
    t41_lce_gain = gain;
    spin_lock_irqsave(&t41_lce_stats_lock, flags);
    if (t41_lce_ready != 1) {
        spin_unlock_irqrestore(&t41_lce_stats_lock, flags);
        ret = -EAGAIN;
        goto done;
    }
    memcpy(s + 0x1898, s + 0x164, 0x1680);
    memcpy(s + 0x2f18, s + 0x17e4, 0xb4);
    t41_lce_ready = -1;
    spin_unlock_irqrestore(&t41_lce_stats_lock, flags);
    ev = t41_tmo_le32(s + 0x58f4) >> 7;
    if (ev != t41_tmo_le32(s + 0x58f8)) {
        t41_lce_put32(s + 0x58f8, ev);
        if (t41_tmo_le32(s + 0x57f0) == 1) {
            t41_dpc_put16(s + 0x57f4, ev);
            t41_lce_put32(s + 0x58fc, 4);
        }
    }
    ret = t41_lce_process(s, T41_LCE_STATE_BYTES, s[0x58fc]) ? -ERANGE : 0;
    if (!ret) {
        t41_lce_put32(s + 0x58fc, 0);
        ret = t41_lce_write_locked(s);
        if (!ret) {
            old = t41_tmo_le32(s + 0x5904) + 1;
            t41_lce_put32(s + 0x5904, old >= 0x20000000 ? 15 : old);
            ++t41_lce_frames;
        }
    }
done:
    t41_lce_error = ret;
    mutex_unlock(&t41_lce_lock);
    return ret;
}

static int t41_lce_read_bank_locked(unsigned int bank)
{
    uint8_t *s = (uint8_t *)(uintptr_t)lce_info;
    uint32_t control = bank ? 0x501d0 : 0x501c0;
    uint32_t sum_control = bank ? 0x50210 : 0x50200;
    uint32_t *hist, *sums;
    unsigned int i;
    if (bank > 1 || !t41_kernel_data_ptr(s))
        return -EINVAL;
    hist = (uint32_t *)(void *)(s + 0x164);
    sums = (uint32_t *)(void *)(s + 0x17e4);
    system_reg_write(control, 0x201);
    for (i = 0; i < 1440; ++i) hist[i] = system_reg_read(control + 8);
    system_reg_write(control, 0x59f0202);
    system_reg_write(sum_control, 0x201);
    for (i = 0; i < 45; ++i) sums[i] = system_reg_read(sum_control + 8);
    system_reg_write(sum_control, 0x2c0202);
    return 0;
}

static void t41_clear_lce_hist_ram(unsigned int bank)
{
    uint32_t control = bank ? 0x501d0U : 0x501c0U;
    uint32_t data = control + 4U;
    unsigned int i;

    system_reg_write(control, 0x00000101U);
    for (i = 0; i < 1440U; ++i)
        system_reg_write(data, 0);
    system_reg_write(control, 0x059f0102U);
}

static void t41_apply_stock_lce_ram_profile(void)
{
    struct t41_dpc_word words[4];
    uint8_t *s;
    unsigned long flags;
    unsigned int i;
    mutex_lock(&t41_lce_lock);
    s = t41_lce_object();
    if (!s || t41_stock_lce_ram_profile > 0)
        goto done;
    t41_lce_error = t41_lce_geometry(s, T41_LCE_STATE_BYTES,
        t41_tmo_le16(s + 0x592a) + 1, t41_tmo_le16(s + 0x5916) + 1, words);
    if (t41_lce_error)
        goto done;
    t41_lce_error = t41_lce_calibrate_locked(s);
    if (t41_lce_error)
        goto done;
    for (i = 0; i < ARRAY_SIZE(words); ++i)
        system_reg_write(words[i].address, words[i].value);
    spin_lock_irqsave(&t41_lce_stats_lock, flags);
    t41_lce_ready = -1;
    memset(s + 0x164, 0, 0x5770 - 0x164);
    t41_clear_lce_hist_ram(0);
    t41_clear_lce_hist_ram(1);
    spin_unlock_irqrestore(&t41_lce_stats_lock, flags);
    t41_lce_identity(s);
    t41_lce_put32(s + 0x58fc, 4);
    t41_lce_error = t41_lce_write_locked(s);
    if (!t41_lce_error)
        t41_top_restore_bypass(BIT(21));
done:
    mutex_unlock(&t41_lce_lock);
}

#include "tx_isp_t41_lsc_runtime.inc"
#include "tx_isp_t41_awb_runtime.inc"

static void t41_apply_stock_spatial_profile(void)
{
    uint32_t gain = READ_ONCE(t41_safe_ae_gain_q16);
    t41_sdns_error = tisp_sdns_all_reg_refresh(0, gain <= (16U << 16) ? gain : 0);
    if (!t41_sdns_error)
        t41_top_restore_bypass(BIT(18));
    t41_ydns_error = tisp_ydns_all_reg_refresh(0, gain <= (16U << 16) ? gain : 0);
    if (!t41_ydns_error)
        t41_top_restore_bypass(BIT(14));
    if (t41_stock_spatial_profile <= 0)
        t41_apply_stock_lce_ram_profile();
    t41_native_lsc_reapply();
}

