int tiziano_load_parameters(uint32_t channel, uintptr_t load_request)
{
    unsigned char *manager;
    unsigned char *payload;
    unsigned char *day_params;
    unsigned char *night_params;
    unsigned char *payload_end;
    unsigned char *sensor_info;
    const char *requested_path;
    struct file *filp;
    loff_t file_size;
    loff_t read_offset = 0;
    uint32_t declared_size;
    uint32_t night_offset;
    uint32_t expected_crc;
    uint32_t crc = 0;
    uint32_t offset;
    ssize_t bytes_read = 0;
    char path[64];
    int ret = -EINVAL;

    if (channel >= ARRAY_SIZE(tparams_day_storage) / sizeof(uint32_t) ||
        !load_request)
        return -EINVAL;

    requested_path = (const char *)(load_request + sizeof(uint32_t));
    t41_note(
           "t41: tisp-load enter channel=%u path=%s\n",
           channel, requested_path);
    if (!requested_path[0] || strnlen(requested_path, sizeof(path)) >= sizeof(path))
        return -ENAMETOOLONG;

    manager = (unsigned char *)(uintptr_t)m_bin;
    if (!manager) {
        manager = private_kmalloc(76, GFP_KERNEL);
        if (!manager)
            return -ENOMEM;
        memset(manager, 0, 76);
        m_bin = (uint32_t)(uintptr_t)manager;
    }
    printk(KERN_WARNING
           "t41: tisp-load manager ready=%p\n", manager);

    snprintf(manager, 8, "%s", "1.00");
    snprintf(bin_version, sizeof(bin_version), "%s", "2.00");
    snprintf(manager + 8, 8, "%s", "t41");
    snprintf(path, sizeof(path), "%s", requested_path);
    memcpy((void *)&st_tisp_com_par, path, sizeof(path));

    filp = private_filp_open(path, O_RDONLY, 0);
    if (IS_ERR(filp)) {
        isp_printf(2, "tiziano_load_parameters: open %s failed (%ld)\n",
                   path, PTR_ERR(filp));
        return PTR_ERR(filp);
    }

    file_size = private_i_size_read(private_file_inode(filp));
    printk(KERN_WARNING
           "t41: tisp-load opened size=%lld\n",
           (long long)file_size);
    if (file_size < 64 || file_size > INT_MAX) {
        ret = -EINVAL;
        goto close_file;
    }

    payload = *(unsigned char **)(manager + 64);
    if (!payload) {
        payload = private_vmalloc((size_t)file_size);
        if (!payload) {
            ret = -ENOMEM;
            goto close_file;
        }
        *(uint32_t *)(manager + 64) = (uint32_t)(uintptr_t)payload;
    }
    printk(KERN_WARNING
           "t41: tisp-load payload ready=%p\n", payload);

    *(uint32_t *)(manager + 68) = (uint32_t)file_size;
    while (bytes_read < file_size) {
        /* A single full-file SFC read can hold this 4.4 kernel in an
         * uninterruptible flash transaction long enough to starve the
         * camera.  Page-sized reads preserve the exact binary while giving
         * IRQ and watchdog work a scheduling point between transactions. */
        unsigned long chunk = min_t(loff_t, file_size - bytes_read,
                                    PAGE_SIZE);
        int chunk_read = kernel_read(filp, read_offset,
                                     payload + bytes_read, chunk);

        if (!bytes_read || bytes_read + chunk_read >= file_size)
            printk(KERN_WARNING
                   "t41: tisp-load read offset=%lld "
                   "requested=%lu returned=%d\n",
                   (long long)read_offset, chunk, chunk_read);
        if (chunk_read <= 0) {
            ret = chunk_read < 0 ? chunk_read : -EIO;
            goto close_file;
        }
        bytes_read += chunk_read;
        read_offset += chunk_read;
        cond_resched();
    }
    if (bytes_read != file_size) {
        ret = bytes_read < 0 ? (int)bytes_read : -EIO;
        goto close_file;
    }

    printk(KERN_WARNING
           "t41: tisp-load close begin\n");
    private_filp_close(filp, NULL);
    filp = NULL;
    printk(KERN_WARNING
           "t41: tisp-load read complete bytes=%lld\n",
           (long long)bytes_read);

    if (memcmp(manager, payload, 8) != 0 &&
        (!init_load_bin || memcmp(bin_version, payload, 8) != 0)) {
        isp_printf(2, "tiziano_load_parameters: bin version mismatch\n");
        goto free_binary;
    }

    memcpy(bin_version, payload, sizeof(bin_version));
    if (memcmp(manager + 8, payload + 8, 8) != 0) {
        isp_printf(2, "tiziano_load_parameters: SoC type mismatch\n");
        goto free_binary;
    }

    declared_size = *(uint32_t *)(payload + 48);
    night_offset = *(uint32_t *)(payload + 52);
    expected_crc = *(uint32_t *)(payload + 60);
    if (declared_size > (uint32_t)file_size - 64 ||
        night_offset > declared_size) {
        isp_printf(2, "tiziano_load_parameters: invalid parameter extents\n");
        goto free_binary;
    }

    /* Stock T41 hashes declared_size bytes beginning immediately after the
     * 64-byte file header.  Keep this exact range: declared_size is a payload
     * length, not an absolute file offset. */
    for (offset = 64; offset < 64 + (declared_size & ~3U); offset += 4) {
        uint32_t word = *(uint32_t *)(payload + offset);

        crc ^= word;
        crc ^= crc_table[crc & 7];
    }
    if (crc != expected_crc) {
        isp_printf(2,
                   "tiziano_load_parameters: CRC mismatch computed=%08x expected=%08x\n",
                   crc, expected_crc);
        goto free_binary;
    }
    printk(KERN_WARNING
           "t41: tisp-load header valid declared=%u night=%u\n",
           declared_size, night_offset);

    sensor_info = *(unsigned char **)((char *)&tsbin + channel * sizeof(uint32_t));
    if (!sensor_info) {
        ret = -ENOMEM;
        goto free_binary;
    }

    snprintf(sensor_info, 8, "%s", manager);
    snprintf(sensor_info + 8, 72, "%s", path);
    day_params = payload + 64;
    night_params = day_params + night_offset;
    payload_end = payload + file_size;
    *(uint32_t *)(manager + 72) = (uint32_t)(uintptr_t)day_params;
    *(uint32_t *)((char *)&tparams_day + channel * sizeof(uint32_t)) =
        (uint32_t)(uintptr_t)day_params;
    *(uint32_t *)((char *)&tparams_night + channel * sizeof(uint32_t)) =
        (uint32_t)(uintptr_t)night_params;
    memcpy((void *)&dnw, payload + 16, sizeof(dnw));

    /* Stock (ELF 0x204fc) passes day_params + 0x1ee40 for the day block,
     * mirroring the night block.  The former payload + 0xf94 pointed into
     * ordinary tuning data: harmless for os04d10, but gc5603 has a non-zero
     * "count" there followed by a NULL address -> oops at boot. */
    if (day_params + 0x1ee40 + 452 <= payload_end)
        tiziano_reserve_reg_write((int8_t)((unsigned char *)&dnw)[0],
                                  (uintptr_t)(day_params + 0x1ee40),
                                  (uintptr_t)night_params);
    printk(KERN_WARNING
           "t41: tisp-load day reserve complete\n");
    if (night_params + 0x1ee40 + 452 <= payload_end)
        tiziano_reserve_reg_write((int8_t)((unsigned char *)&dnw)[2],
                                  (uintptr_t)(night_params + 0x1ee40),
                                  (uintptr_t)night_params);
    printk(KERN_WARNING
           "t41: tisp-load night reserve complete\n");

    if (night_params + 0x1efc0 < payload_end && night_params[0x1efc0]) {
        size_t available = payload_end - (night_params + 0x1efc0);
        size_t version_len = strnlen(night_params + 0x1efc0, available);

        version_len = min_t(size_t, version_len, 67);
        memcpy(sensor_info + 80, night_params + 0x1efc0, version_len);
        sensor_info[80 + version_len] = '\0';
        printk(KERN_WARNING "[CVersion] %s\n", sensor_info + 80);
    }

    init_load_bin = 1;
    t41_note(
           "t41: tisp-load exit ret=0\n");
    return 0;

close_file:
    if (filp && !IS_ERR(filp))
        private_filp_close(filp, NULL);
free_binary:
    payload = *(unsigned char **)(manager + 64);
    if (payload)
        private_vfree(payload);
    private_kfree(manager);
    m_bin = 0;
    *(uint32_t *)((char *)&tparams_day + channel * sizeof(uint32_t)) = 0;
    *(uint32_t *)((char *)&tparams_night + channel * sizeof(uint32_t)) = 0;
    return ret;
}

