	static const int8_t callback_index[8] = { 0, 1, 2, 3, 4, -1, 5, 6 };
	char *core;
	char *outpads;
	char *channels;
	void *owner;
	event_fn *ops;
	event_fn callback;
	uint32_t index;
	uint32_t pad_index;

