    *(uint16_t *)(config + 62) = *(uint16_t *)(attr + 170);
    *(uint16_t *)(config + 64) = *(uint16_t *)(attr + 172);
    *(uint16_t *)(config + 66) = *(uint16_t *)(attr + 174);
